public static Type resolveReturnType(Type baseType, Type overridingType) {
  if (baseType instanceof Class && overridingType instanceof Class &&
      ((Class<?>) baseType).isAssignableFrom((Class<?>) overridingType)) {
    // NOTE: javac generates multiple same methods for multiple inherited generic interfaces
    return overridingType;
  }
  if (baseType instanceof Class && overridingType instanceof ParameterizedType) {
    // NOTE: javac will generate multiple methods with different return types
    // base interface declares generic method, override declares parameterized generic method
    return overridingType;
  }
  if (baseType instanceof Class && overridingType instanceof TypeVariable) {
    // NOTE: javac will generate multiple methods with different return types
    // base interface declares non generic method, override declares generic method
    return overridingType;
  }
  return baseType;
}

public AISMessageParser(AISSentence... sentences) {
    int index = 1;
    for (AISSentence s : sentences) {
        if (s.isFragmented() && s.getFragmentNumber() != index++) {
            throw new IllegalArgumentException("Incorrect order of AIS sentences");
        }
        this.append(s.getPayload(), s.getFragmentNumber(), s.getFillBits());
    }
    this.decoder = new Sixbit(this.message, this.fillBits);
}

private Sentence createParserImpl(String sid, Object param) {

	if (!hasParser(sid)) {
		String msg = String.format("Parser for type '%s' not found", sid);
		throw new UnsupportedSentenceException(msg);
	}

	Sentence parser = null;
	Class<?> klass = param.getClass();

	try {
		Class<? extends SentenceParser> c = parsers.get(sid);
		Constructor<? extends SentenceParser> co = c.getConstructor(klass);
		parser = co.newInstance(param);
	} catch (NoSuchMethodException e) {
		String name = klass.getName();
		String msg = "Constructor with %s parameter not found";
		throw new IllegalStateException(String.format(msg, name), e);
	} catch (InstantiationException e) {
		throw new IllegalStateException("Unable to instantiate parser", e);
	} catch (IllegalAccessException e) {
		throw new IllegalStateException("Unable to access parser", e);
	} catch (InvocationTargetException e) {
		throw new IllegalStateException(
			"Unable to invoke parser constructor", e);
	}

	return parser;
}

