static void bind(ServiceLocator locator, Iterable<Binding> descriptors) {
    DynamicConfiguration dc = getDynamicConfiguration(locator);
    for (Binding binding : descriptors) {
        bindBinding(locator, dc, binding);
    }
    dc.commit();
}

