public static Object fromJava(Object o) {
    if (o instanceof Function || o instanceof Proxy) {
        return o;
    } else if (o instanceof List) {
        return new JsList((List) o);
    } else if (o instanceof Map) {
        return new JsMap((Map) o);
    } else if (o instanceof Node) {
        return new JsXml((Node) o);
    } else {
        return o;
    }
}

public void put(String key, Object value) {
    bindings.putMember(key, JsValue.fromJava(value));
}

public static Value that(Object actual) {
    return new Value(parseIfJsonOrXmlString(actual), true);
}

public static Object parseIfJsonOrXmlString(Object o) {
    if (o instanceof String) {
        String s = (String) o;
        if (s.isEmpty()) {
            return o;
        } else if (JsonUtils.isJson(s)) {
            return Json.of(s).value();
        } else if (XmlUtils.isXml(s)) {
            return XmlUtils.toXmlDoc(s);
        } else {
            if (s.charAt(0) == '\\') {
                return s.substring(1);
            }
        }
    }
    return o;
}
